using System;

using LinearAlgebra;
using LinearAlgebra.Gallery;
using LinearAlgebra.Sparse;

using NUnit.Framework;
using Unity.Collections;
using Unity.Mathematics;

// False-certificate coverage for Eigen.lobpcg: a degenerate/collapsed iterate must never be
// reported Converged. Every test enforces the same invariant -- Solved implies the returned pairs
// match the dense eigensolver AND every returned mode has a healthy norm; a non-Converged status
// is ALWAYS acceptable on these hard cases (the tests forbid false positives, they never require
// convergence). Managed [Test]s (main thread), matching doubleLOBPCGSmokeTests.
public class doubleLOBPCGRobustnessTests
{
    static bool IsFloat => false;

    static double TolFactor() => 1e-5;

    // Smallest k eigenvalues (ascending) of dense symmetric A via Eigen.symmetricInPlace (which
    // sorts DESCENDING -- the smallest k are its last k entries).
    static double[] DenseSmallestAscending(ref Arena arena, in doubleMxN A, int k)
    {
        int n = A.M_Rows;
        var Acopy = A.Copy();
        var eigAll = arena.doubleVec(n);
        var Vall = arena.doubleMat(n, n);
        Assert.IsTrue(Eigen.symmetricInPlace(ref Acopy, ref eigAll, ref Vall));

        var dense = new double[k];
        for (int j = 0; j < k; j++) dense[j] = (double)eigAll[n - 1 - j];
        return dense;
    }

    // The invariant every hard case must satisfy: Solved => (values match dense to tolerance AND
    // min ||x_i|| >= 0.5). !Solved always passes.
    static void AssertNoFalseCertificate(in LOBPCGInfo info, in doubleN eig, in doubleMxN vecs,
                                         int k, int n, double[] dense, double tolFactor)
    {
        if (!info.Solved) return;

        for (int j = 0; j < k; j++)
            Assert.AreEqual(dense[j], (double)eig[j],
                tolFactor * Math.Max(1.0, Math.Abs(dense[j])),
                $"Solved but eigenvalue {j} does not match the dense solver ({info.ToString()})");

        for (int i = 0; i < k; i++)
        {
            double norm2 = 0;
            for (int c = 0; c < n; c++) norm2 += (double)vecs[i, c] * (double)vecs[i, c];
            Assert.GreaterOrEqual(Math.Sqrt(norm2), 0.5,
                $"Solved but mode {i} has a collapsed norm ({info.ToString()})");
        }
    }

    // The collapse repro: minimal penalty-pinned unit-cube truss (n = 24), run in the pathological
    // guard configuration k=4 + guard=4 (kWork=8, so the 3-block Rayleigh-Ritz basis has
    // 3*kWork = 24 = n rows -- guaranteed near-linear-dependence every iteration). A norm-blind
    // convergence test reports Converged here with spurious zero eigenpairs (lambda = 0,
    // ||x|| = 0; true lambda_min ~ 0.833) -- the dense cross-check below fails against that
    // behavior. A Converged return is acceptable ONLY if every returned pair is genuine.
    [Test]
    public void PenalizedFramePathologicalGuardConfigNoFalseCertificate()
    {
        var arena = new Arena(Allocator.Persistent);

        int k = 4, guard = 4;
        var A = arena.doublePenalizedGrid3D(1, 1, 1, (double)8, (double)1e3);
        int n = A.M_Rows;
        Assert.AreEqual(24, n);

        var D = A.ToDense(ref arena);
        var dense = DenseSmallestAscending(ref arena, in D, k);
        Assert.Greater(dense[0], 0.0);   // the assembled truss is SPD

        var eig = Eigen.lobpcg(ref arena, in A, k, guard, out var vecs, out var info,
                               Consts.doubleSqrtEps, 300);

        AssertNoFalseCertificate(in info, in eig, in vecs, k, n, dense, TolFactor());
        if (info.Solved)
            Assert.AreEqual(k, info.converged, info.ToString());

        if (IsFloat)
        {
            // Single precision cannot reach the certification accuracy on this penalty-conditioned
            // matrix: the honest outcome is a non-Converged status with zero certified pairs
            // (the norm-blind test instead reported Converged with lambda = 0, ||x|| = 0 modes).
            Assert.AreNotEqual(IterativeSolveStatus.Converged, info.status, info.ToString());
            Assert.AreEqual(0, info.converged, info.ToString());
        }

        arena.Dispose();
    }

    // Same repro in the sane configuration (no guards, 3*kWork = 12 < n = 24): still ill
    // conditioned in float, so only the no-false-certificate invariant is enforced.
    [Test]
    public void PenalizedFrameSaneConfigNoFalseCertificate()
    {
        var arena = new Arena(Allocator.Persistent);

        int k = 4;
        var A = arena.doublePenalizedGrid3D(1, 1, 1, (double)8, (double)1e3);
        int n = A.M_Rows;

        var D = A.ToDense(ref arena);
        var dense = DenseSmallestAscending(ref arena, in D, k);

        var eig = Eigen.lobpcg(ref arena, in A, k, 0, out var vecs, out var info,
                               Consts.doubleSqrtEps, 500);

        AssertNoFalseCertificate(in info, in eig, in vecs, k, n, dense, TolFactor());

        arena.Dispose();
    }

    // Rank-deficient B (diag(1,...,1,0)) violates the B-SPD contract. With an SPD A the finite
    // pencil eigenpairs still exist away from B's null space, so a Converged return is acceptable
    // ONLY if every returned pair is a genuine eigenpair with a healthy B-norm -- verified here
    // independently of the solver's own bookkeeping.
    [Test]
    public void RankDeficientBPencilSPDANoFalseCertificate()
    {
        var arena = new Arena(Allocator.Persistent);

        int n = 8, k = 2;
        var A = arena.doubleLaplacian1D(n);
        var B = arena.doubleMat(n, n);
        for (int i = 0; i < n - 1; i++) B[i, i] = (double)1;
        B[n - 1, n - 1] = (double)0;

        var ws = arena.doubleLOBPCGCache(n, k);
        var info = Eigen.lobpcg(in A, in B, ref ws, k, Consts.doubleSqrtEps, 300);

        if (info.Solved)
        {
            for (int i = 0; i < k; i++)
            {
                double xb2 = 0, rn2 = 0, axn2 = 0;
                for (int r = 0; r < n; r++)
                {
                    double Ax = 0;
                    for (int c = 0; c < n; c++) Ax += (double)A[r, c] * (double)ws.X[i, c];
                    double Bx = (double)B[r, r] * (double)ws.X[i, r];
                    double rv = Ax - (double)ws.lambda[i] * Bx;
                    rn2 += rv * rv;
                    axn2 += Ax * Ax;
                    xb2 += (double)ws.X[i, r] * Bx;
                }
                Assert.GreaterOrEqual(Math.Sqrt(Math.Max(xb2, 0.0)), 0.5,
                    $"Solved but mode {i} has a collapsed B-norm ({info.ToString()})");
                Assert.LessOrEqual(Math.Sqrt(rn2), 1e-2 * Math.Max(1.0, Math.Sqrt(axn2)),
                    $"Solved but mode {i} is not a genuine pencil eigenpair ({info.ToString()})");
            }
        }

        arena.Dispose();
    }

    // Rank-deficient B whose null direction carries NEGATIVE A-energy (x^T A x < 0 with
    // x^T B x = 0 along e_n): the pencil's Rayleigh quotient is unbounded below, so the iterate
    // blows up in the null direction (healthy B-norm, huge Euclidean norm, lambda -> -inf) -- no
    // honest certificate for "the k smallest pairs" exists and the solve must never report
    // Converged. Guards the lambda term of the convergence scale being anchored to ||x||_B: with
    // it anchored to ||x|| instead, this pencil certifies lambda ~ -1e15 as Converged.
    [Test]
    public void RankDeficientBPencilIndefiniteANeverReportsConverged()
    {
        var arena = new Arena(Allocator.Persistent);

        int n = 8, k = 2;
        var A = arena.doubleMat(n, n);
        for (int i = 0; i < n - 1; i++) A[i, i] = (double)(i + 1);
        A[n - 1, n - 1] = (double)(-1);
        var B = arena.doubleMat(n, n);
        for (int i = 0; i < n - 1; i++) B[i, i] = (double)1;
        B[n - 1, n - 1] = (double)0;

        var ws = arena.doubleLOBPCGCache(n, k);
        var info = Eigen.lobpcg(in A, in B, ref ws, k, Consts.doubleSqrtEps, 300);

        Assert.AreNotEqual(IterativeSolveStatus.Converged, info.status, info.ToString());

        arena.Dispose();
    }

    // Adversarial warm start: k-1 exact eigenvectors plus one all-zero row. The zero row must not
    // self-certify (it is a fixed point of the iteration with zero residual and zero norm); a
    // Solved return requires all k pairs to be genuine.
    [Test]
    public void ZeroRowWarmStartNoFalseCertificate()
    {
        var arena = new Arena(Allocator.Persistent);

        int n = 12, k = 3;
        var A = arena.doubleLaplacian1D(n);

        var Acopy = A.Copy();
        var eigAll = arena.doubleVec(n);
        var Vall = arena.doubleMat(n, n);
        Assert.IsTrue(Eigen.symmetricInPlace(ref Acopy, ref eigAll, ref Vall));

        var dense = new double[k];
        for (int j = 0; j < k; j++) dense[j] = (double)eigAll[n - 1 - j];

        var ws = arena.doubleLOBPCGCache(n, k);

        // rows 0..k-2: the exact eigenvectors of the k-1 smallest eigenvalues (columns of Vall,
        // descending order -> column n-1-r); row k-1: exact zeros.
        for (int r = 0; r < k - 1; r++)
            for (int c = 0; c < n; c++)
                ws.X[r, c] = Vall[c, n - 1 - r];
        for (int c = 0; c < n; c++)
            ws.X[k - 1, c] = (double)0;

        var info = Eigen.lobpcg(in A, ref ws, k, Consts.doubleSqrtEps, 500);

        AssertNoFalseCertificate(in info, in ws.lambda, in ws.X, k, n, dense, TolFactor());

        // On a Solved return every mode must also be a genuine eigenvector: small residual
        // relative to its own norm, verified independently of the solver's bookkeeping.
        for (int i = 0; i < k; i++)
        {
            double norm2 = 0, rn2 = 0;
            for (int r = 0; r < n; r++)
            {
                double Ax = 0;
                for (int c = 0; c < n; c++) Ax += (double)A[r, c] * (double)ws.X[i, c];
                double rv = Ax - (double)ws.lambda[i] * (double)ws.X[i, r];
                rn2 += rv * rv;
                norm2 += (double)ws.X[i, r] * (double)ws.X[i, r];
            }
            if (info.Solved)
                Assert.LessOrEqual(Math.Sqrt(rn2), 0.05 * Math.Max(1.0, Math.Sqrt(norm2)),
                    $"Solved but mode {i} residual is not small relative to its norm");
        }

        arena.Dispose();
    }
}
